#include "RouteUI.h"
#include "UiLayout.h"
#include "lvgl_v8_port.h"
namespace { lv_obj_t *button(lv_obj_t *p,const UiLayout &layout,const char *t,int x,lv_event_cb_t cb,void *u) { auto *b=lv_btn_create(p); lv_obj_set_size(b,layout.width(100),layout.height(38)); lv_obj_align(b,LV_ALIGN_TOP_MID,layout.x(x),layout.y(350)); lv_obj_set_style_bg_color(b,lv_color_hex(0x263746),0); auto *l=lv_label_create(b); lv_label_set_text(l,t); lv_obj_center(l); lv_obj_add_event_cb(b,cb,LV_EVENT_CLICKED,u); return b; } }
void RouteUI::begin(StartCallback start,BackCallback back) { lvgl_port_lock(-1); startCallback=start; backCallback=back; const UiLayout layout(profile); screen=lv_obj_create(nullptr); lv_obj_clear_flag(screen,LV_OBJ_FLAG_SCROLLABLE); lv_obj_set_style_bg_color(screen,lv_color_hex(0x080C10),0); auto *title=lv_label_create(screen); lv_label_set_text(title,"ROUTES"); lv_obj_set_style_text_font(title,&lv_font_montserrat_24,0); lv_obj_align(title,LV_ALIGN_TOP_MID,0,layout.y(36)); status=lv_label_create(screen); lv_obj_set_width(status,layout.width(360)); lv_obj_set_style_text_align(status,LV_TEXT_ALIGN_CENTER,0); lv_obj_set_style_text_font(status,&lv_font_montserrat_14,0); lv_obj_set_style_text_color(status,lv_color_hex(0x8899AA),0); lv_obj_align(status,LV_ALIGN_TOP_MID,0,layout.y(76)); roller=lv_roller_create(screen); lv_obj_set_width(roller,layout.width(340)); lv_obj_set_style_text_font(roller,&lv_font_montserrat_18,LV_PART_MAIN); lv_roller_set_visible_row_count(roller,5); lv_obj_align(roller,LV_ALIGN_CENTER,0,0); button(screen,layout,"Start",-55,startEvent,this); button(screen,layout,"Back",55,backEvent,this); lvgl_port_unlock(); }
void RouteUI::show(const std::vector<RouteDefinition>& routes,bool ready) { lvgl_port_lock(-1); if(!visible)returnScreen=lv_scr_act(); ids.clear(); String options; for(const auto &r:routes){if(options.length())options+='\n';options+=String(r.id);if(r.name.length())options+=" - "+r.name;if(r.automation)options+=" [AUTO]";ids.push_back(r.id);} if(!options.length())options="No routes";lv_label_set_text(status,!ready?"Loading route list...":routes.empty()?"No routes configured":"Select a route, then choose Start");lv_roller_set_options(roller,options.c_str(),LV_ROLLER_MODE_NORMAL);visible=true;lv_scr_load(screen);lvgl_port_unlock(); }
void RouteUI::move(int delta){if(!visible||ids.empty())return;int s=static_cast<int>(lv_roller_get_selected(roller))+delta;s=s<0?0:s;s=s>=static_cast<int>(ids.size())?ids.size()-1:s;lv_roller_set_selected(roller,s,LV_ANIM_OFF);} void RouteUI::startSelected(){uint16_t s=lv_roller_get_selected(roller);if(visible&&startCallback&&s<ids.size())startCallback(ids[s]);} void RouteUI::hide(){if(visible&&returnScreen)lv_scr_load(returnScreen);visible=false;} void RouteUI::startEvent(lv_event_t *e){static_cast<RouteUI*>(lv_event_get_user_data(e))->startSelected();} void RouteUI::backEvent(lv_event_t *e){auto *u=static_cast<RouteUI*>(lv_event_get_user_data(e));if(u->backCallback)u->backCallback();}
